import{_ as e,c as p,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"50、【鼎】 巽下離上","description":"周易闡真 - 50、【鼎】 巽下離上","frontmatter":{"title":"50、【鼎】 巽下離上","description":"周易闡真 - 50、【鼎】 巽下離上"},"headers":[],"relativePath":"classics/chanzhen/051.md","filePath":"classics/chanzhen/051.md"}'),s={name:"classics/chanzhen/051.md"};function n(c,a,i,o,l,h){return t(),p("div",null,[...a[0]||(a[0]=[r('<blockquote><p>彖曰：鼎，象也；以木巽火，亨飪也。聖人亨以享上帝，而大亨以養聖賢。巽而耳目聰明，柔進而上行，得中而應乎剛，是以元亨。</p></blockquote><h1 id="_50、【鼎】-巽下離上" tabindex="-1">50、【鼎】 巽下離上 <a class="header-anchor" href="#_50、【鼎】-巽下離上" aria-label="Permalink to “50、【鼎】 巽下離上”">​</a></h1><p>初六：鼎顛趾，利出否。得妾以其子，無咎。</p><p>九二：鼎有實。我仇有疾，不我能即，吉。</p><p>九三：鼎耳革，其行塞。雉膏不食，方雨虧悔，終吉。</p><p>九四：鼎折足，覆公束副本，其形渥，兇。</p><p>六五：鼎黃耳，金鉉，利貞。</p><p>上九：鼎玉鉉，大吉，無不利。</p><h2 id="孔易闡真-​" tabindex="-1">孔易闡真 ​ <a class="header-anchor" href="#孔易闡真-​" aria-label="Permalink to “孔易闡真 ​”">​</a></h2><p>大象：木上有火，鼎。君子以正位凝命。</p><p>鼎者，取其煅煉也。上離火，下巽木，是木上有火也。木火一處，煅煉諸物，鼎之象也。</p><p>君子有見於此，知鼎所以烹物，非木火之功不能成熟；道所以載命，非巽明之功不能凝結。以是正於當居之位，漸次修持，而凝其命焉。正者，不偏不倚、不隱不瞞；位者，陰陽之門、元關一竅；凝者，聚而不散；命者，先天祖氣。能正於位，則所位者正，以漸而入，以明而行，仁義禮智根於心，四象和合，五行攢簇，氣足神全，而命凝矣。凝命之道，全在正位工夫。不能正位，是不知元關；不知元關，便不知命。不知命而著空執相、認假為真，入於旁門曲徑，不但不能凝命，而且有以傷命。命為先天正氣，命即是正，正即是命。正位者，即是謹守元關一點正氣，文烹武煉、日乾夕惕，不使有些子客氣雜於鼎爐之中，不正而必期其正，不凝而必期其凝，由勉強而歸自然，由散亂而整齊，一正位而凝命之功盡矣。但患人不能正位耳。果能正位，即能凝命。所謂“言語不通非眷屬，工夫不到不方圓”也。</p><h2 id="悟元子註解-​" tabindex="-1">悟元子註解 ​ <a class="header-anchor" href="#悟元子註解-​" aria-label="Permalink to “悟元子註解 ​”">​</a></h2><p>仇，音讎。束副本，音速。渥，音握。鉉，音泫。</p><p>鼎者，烹煎鍛鍊之器，所以取新也。卦德上離明，下巽入，累進而生明，其心日下，其明日增，下而又下，增而又增；且卦體二五，虛實相應，明中能虛，巽中能實。虛明，則明無不照，而富貴窮通不能動其心；實巽，則德無不修，而吉凶禍福不能亂其性。巽進而生明，虛明而巽進，虛實相濟，如火得木而光華倍增，如木遇火而濁氣悉化，有煅煉烹煎之義，故謂鼎。此煅煉大藥之卦，承上井卦而來。井者，巽進而通險，險通則後天所陷之真陽已出，大藥已生，可以巽進其明，運火煅煉矣。鍛鍊之功，所以消化陰氣、堅固陽氣，使生者而熟，舊者而新，能以明心，能以凝命，是以鼎本元吉，而又有亨道也。</p><p>元者，善之長生之機。鼎之烹煎大藥，即烹煎此生機不壞，萬劫長存耳。但是道也，有火候，有次序，毫毛差殊，金丹不成，是在人先須窮究實理耳。</p><p>初六，在鼎之下，為下德之人，性質昏愚，其趾多顛而不正，欲立其鼎，不利於取新，利於去舊，能去其舊，則否出而趾不顛，週週正正，止於其所而不遷，如妾本下賤，生子則貴，亦可無咎，其初之有顛矣。此煉己之事，為立鼎之初功也。</p><p>九二，剛而得中，真陽返回，已實其腹矣。腹既能實，道心常存，人心不生，如我仇有疾，不我能即矣。此養道心，自無人心也。</p><p>九三，獨剛無柔，實腹之後，不知虛心，是革去鼎耳。雖能了命，未能了性，其行塞窒，不能通前達後，壽同天地一愚夫，如不食雉膏也。幸其剛而守正，方雨行塞，有虧即悔，悔則自能虛心，既能虛心，其行不塞，由了命而又了性，終得以吉全之。此有道心，又虛人心也。</p><p>九四，由巽入明，金丹有象，正當防危慮險，用天然真火，煅盡後天群陰之時。乃剛為柔牽，鼎足又折，起人心而傷道心，如公束副本 覆傾命寶，得而復失，形雖存而神已喪，其兇不可言矣。此起人心，有昧道心也。</p><p>六五，柔順得中，虛人心而用道心，如鼎黃耳，金鉉也。黃耳者，鼎耳之中虛。金鉉者，鼎扃之中實。鼎耳貫鼎扃，剛柔相濟，虛實相應，火即是藥，藥即是火。當此之時，利於貞一不二，防危慮險，不必分外增減矣。此虛人心而養道心也。</p><p>上九，在鼎之終，鼎新之功已盡，有無俱不立，物我悉歸空，靜則無為，動則自然，剛即是柔，柔即是剛，不用剛而剛全，不用明而明通，已到至誠可以前知地位，如鼎之玉鉉也。鉉而至玉，剛柔如一，氣質俱化，形神俱妙，與道合真，乃修道之極功，聖賢之全能，超出乎陰陽之外，而不為陰陽所拘，是以大吉無不利。此道心人心俱皆混化也。</p><p>修鼎之功，有剛有柔，有進有退，有增有減，不到有無不立、神化不測之地，不為極功。若不知剛柔、進退、增減之法，不落於三之鼎耳革，即歸於四之覆公束副本，毫髮之差，千里之失。修道者，可不巽緩進明，謹慎火候乎？</p>',23)])])}const m=e(s,[["render",n]]);export{d as __pageData,m as default};
